import{_ as a}from"./chunks/Collection体系图.C6I1jdrs.js";import{_ as e}from"./chunks/Map体系图.C8vKHoCH.js";import{_ as r}from"./chunks/集合体系图.CJHl1Wpz.js";import{c as d,Q as o,j as l,m as s}from"./chunks/framework.CHJbb1iY.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"aside":"right","outline":[2,3]},"headers":[],"relativePath":"docs/Java/第二阶段/集合/85.集合总结.md","filePath":"docs/Java/第二阶段/集合/85.集合总结.md"}'),h={name:"docs/Java/第二阶段/集合/85.集合总结.md"};function n(i,t,p,c,b,u){return o(),l("div",null,[...t[0]||(t[0]=[s('<h1 style="text-align:center;font-weight:bold;">集合的总结</h1><hr><h2 id="⭐-集合体系回顾" tabindex="-1">⭐ 集合体系回顾 <a class="header-anchor" href="#⭐-集合体系回顾" aria-label="Permalink to &quot;⭐ 集合体系回顾&quot;">​</a></h2><h3 id="collection" tabindex="-1">Collection <a class="header-anchor" href="#collection" aria-label="Permalink to &quot;Collection&quot;">​</a></h3><br><img src="'+a+'" style="width:800px;margin:0px auto;"><h3 id="map" tabindex="-1">Map <a class="header-anchor" href="#map" aria-label="Permalink to &quot;Map&quot;">​</a></h3><br><img src="'+e+'" style="width:800px;margin:0px auto;"><h3 id="集合体系" tabindex="-1">集合体系 <a class="header-anchor" href="#集合体系" aria-label="Permalink to &quot;集合体系&quot;">​</a></h3><p><img src="'+r+'" alt="alt text"></p><h2 id="线程安全" tabindex="-1">线程安全 <a class="header-anchor" href="#线程安全" aria-label="Permalink to &quot;线程安全&quot;">​</a></h2><blockquote><h4 id="只有-vector、hashtable、properties-是线程安全的-其余都不是线程的" tabindex="-1">只有 <span style="color:red;">Vector、Hashtable、Properties</span> 是线程安全的，其余都不是线程的 <a class="header-anchor" href="#只有-vector、hashtable、properties-是线程安全的-其余都不是线程的" aria-label="Permalink to &quot;只有 &lt;span style=&quot;color:red&quot;&gt;Vector、Hashtable、Properties&lt;/span&gt; 是线程安全的，其余都不是线程的&quot;">​</a></h4></blockquote><h2 id="集合类及其特点总结" tabindex="-1">集合类及其特点总结 <a class="header-anchor" href="#集合类及其特点总结" aria-label="Permalink to &quot;集合类及其特点总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类/接口</th><th>所属接口</th><th>底层实现</th><th>主要特点</th></tr></thead><tbody><tr><td>Collection</td><td><span style="color:red;">接口</span></td><td>实现了 Iterator 接口</td><td>所有集合的顶层父接口</td></tr><tr><td>List</td><td><span style="color:red;">接口</span></td><td>实现了 Collection 接口</td><td><span style="color:red;">有序、可重复</span>元素</td></tr><tr><td>ArrayList</td><td>List</td><td>动态数组</td><td>查询快、增删慢</td></tr><tr><td>Vector</td><td>List</td><td>动态数组</td><td>查询快、效率低</td></tr><tr><td>LinkedList</td><td>List</td><td>双向链表</td><td>增删快、查询慢、可做队列</td></tr><tr><td>Set</td><td><span style="color:red;">接口</span></td><td>实现了 Collection 接口</td><td><span style="color:red;">无序、不重复</span>元素</td></tr><tr><td>HashSet</td><td>Set</td><td>HashMap</td><td>查询快、不保证顺序</td></tr><tr><td>LinkedHashSet</td><td>Set</td><td>LinkedHashMap</td><td><span style="color:red;">有序</span>（插入顺序）</td></tr><tr><td>TreeSet</td><td>Set</td><td>TreeMap（红黑树）</td><td><span style="color:red;">可排序</span>，有序</td></tr><tr><td>Map</td><td><span style="color:red;">接口</span></td><td>实现了 Collection 接口</td><td>键值对集合，键唯一</td></tr><tr><td>HashMap</td><td>Map</td><td>数组+单链表+红黑树</td><td>查询快、不保证顺序</td></tr><tr><td>LinkedHashMap</td><td>Map</td><td>HashMap + <span style="color:red;">双向链表</span></td><td>有序（插入顺序）</td></tr><tr><td>Hashtable</td><td>Map</td><td>哈希表</td><td><span style="color:red;">效率低</span></td></tr><tr><td>Properties</td><td>Map</td><td>继承了 Hashtable</td><td>属性配置专用，键值为字符串</td></tr><tr><td>TreeMap</td><td>Map</td><td>红黑树（Entry 节点）</td><td><span style="color:red;">可排序</span>，按 key 有序</td></tr></tbody></table><h2 id="集合选择" tabindex="-1">集合选择 <a class="header-anchor" href="#集合选择" aria-label="Permalink to &quot;集合选择&quot;">​</a></h2><h4 id="根据存储元素确定集合的存储类型" tabindex="-1">根据存储元素确定集合的<span style="color:red;">存储类型</span> <a class="header-anchor" href="#根据存储元素确定集合的存储类型" aria-label="Permalink to &quot;根据存储元素确定集合的&lt;span style=&quot;color:red&quot;&gt;存储类型&lt;/span&gt;&quot;">​</a></h4><blockquote><h4 id="单列集合-存储一个值" tabindex="-1">单列集合：存储一个值 <a class="header-anchor" href="#单列集合-存储一个值" aria-label="Permalink to &quot;单列集合：存储一个值&quot;">​</a></h4><h4 id="双列集合-存储键值对-key-value" tabindex="-1">双列集合：存储键值对（Key - Value） <a class="header-anchor" href="#双列集合-存储键值对-key-value" aria-label="Permalink to &quot;双列集合：存储键值对（Key - Value）&quot;">​</a></h4></blockquote><h4 id="👉-单列集合-collection-接口" tabindex="-1">👉 单列集合：Collection 接口 <a class="header-anchor" href="#👉-单列集合-collection-接口" aria-label="Permalink to &quot;👉 单列集合：Collection 接口&quot;">​</a></h4><h4 id="_1-允许重复-list-接口" tabindex="-1">（1）允许重复：List 接口 <a class="header-anchor" href="#_1-允许重复-list-接口" aria-label="Permalink to &quot;（1）允许重复：List 接口&quot;">​</a></h4><blockquote><h4 id="增删多-linkedlist-底层维护了一个双向链表" tabindex="-1">增删多：LinkedList（底层维护了一个<span style="color:red;">双向链表</span>） <a class="header-anchor" href="#增删多-linkedlist-底层维护了一个双向链表" aria-label="Permalink to &quot;增删多：LinkedList（底层维护了一个&lt;span style=&quot;color:red&quot;&gt;双向链表&lt;/span&gt;）&quot;">​</a></h4><h4 id="改查多-arraylist-底层维护-object-类型的数组" tabindex="-1">改查多：ArrayList（底层维护 Object 类型的数组） <a class="header-anchor" href="#改查多-arraylist-底层维护-object-类型的数组" aria-label="Permalink to &quot;改查多：ArrayList（底层维护 Object 类型的数组）&quot;">​</a></h4></blockquote><h4 id="_2-不允许重复-set-接口" tabindex="-1">（2）不允许重复：Set 接口 <a class="header-anchor" href="#_2-不允许重复-set-接口" aria-label="Permalink to &quot;（2）不允许重复：Set 接口&quot;">​</a></h4><blockquote><h4 id="无序-hashset-底层是-hashmap-底层结构-数组-链表-红黑树" tabindex="-1">无序：HashSet（底层是 <span style="color:red;">HashMap</span>，底层结构：<span style="color:red;">数组+链表+红黑树</span>） <a class="header-anchor" href="#无序-hashset-底层是-hashmap-底层结构-数组-链表-红黑树" aria-label="Permalink to &quot;无序：HashSet（底层是 &lt;span style=&quot;color:red&quot;&gt;HashMap&lt;/span&gt;，底层结构：&lt;span style=&quot;color:red&quot;&gt;数组+链表+红黑树&lt;/span&gt;）&quot;">​</a></h4><h4 id="排序-treeset" tabindex="-1">排序：TreeSet <a class="header-anchor" href="#排序-treeset" aria-label="Permalink to &quot;排序：TreeSet&quot;">​</a></h4><h4 id="插入和取出顺序一致-linkedhashset-底层是-linkedhashmap-底层结构-数组-双向链表" tabindex="-1">插入和取出<span style="color:red;">顺序一致</span>：LinkedHashSet（底层是 <span style="color:red;">LinkedHashMap</span>，底层结构：<span style="color:red;">数组 + 双向链表</span>） <a class="header-anchor" href="#插入和取出顺序一致-linkedhashset-底层是-linkedhashmap-底层结构-数组-双向链表" aria-label="Permalink to &quot;插入和取出&lt;span style=&quot;color:red&quot;&gt;顺序一致&lt;/span&gt;：LinkedHashSet（底层是 &lt;span style=&quot;color:red&quot;&gt;LinkedHashMap&lt;/span&gt;，底层结构：&lt;span style=&quot;color:red&quot;&gt;数组 + 双向链表&lt;/span&gt;）&quot;">​</a></h4></blockquote><h4 id="👉-双列集合-键值对-map-接口" tabindex="-1">👉 双列集合（键值对）：Map 接口 <a class="header-anchor" href="#👉-双列集合-键值对-map-接口" aria-label="Permalink to &quot;👉 双列集合（键值对）：Map 接口&quot;">​</a></h4><h4 id="_1-键值对-hashmap-底层采用哈希表-hash-table-通过哈希函数对键进行散列-存储元素" tabindex="-1">（1）键值对：HashMap（底层采用哈希表（Hash Table），通过哈希函数对键进行散列，存储元素） <a class="header-anchor" href="#_1-键值对-hashmap-底层采用哈希表-hash-table-通过哈希函数对键进行散列-存储元素" aria-label="Permalink to &quot;（1）键值对：HashMap（底层采用哈希表（Hash Table），通过哈希函数对键进行散列，存储元素）&quot;">​</a></h4><h4 id="_2-键值对-treemap-底层采用红黑树" tabindex="-1">（2）键值对：TreeMap（底层采用红黑树） <a class="header-anchor" href="#_2-键值对-treemap-底层采用红黑树" aria-label="Permalink to &quot;（2）键值对：TreeMap（底层采用红黑树）&quot;">​</a></h4><blockquote><h4 id="_1-可以传入-comparator-比较器-指定添加顺序" tabindex="-1">1. 可以传入 Comparator 比较器，指定添加顺序 <a class="header-anchor" href="#_1-可以传入-comparator-比较器-指定添加顺序" aria-label="Permalink to &quot;1. 可以传入 Comparator 比较器，指定添加顺序&quot;">​</a></h4><h4 id="_2-不允许空键空值" tabindex="-1">2. <span style="color:red;">不允许空键空值</span> <a class="header-anchor" href="#_2-不允许空键空值" aria-label="Permalink to &quot;2. &lt;span style=&quot;color:red&quot;&gt;不允许空键空值&lt;/span&gt;&quot;">​</a></h4></blockquote><h4 id="_3-插入和取出顺序一致-linkedhashmap" tabindex="-1">（3）插入和取出顺序一致：LinkedHashMap <a class="header-anchor" href="#_3-插入和取出顺序一致-linkedhashmap" aria-label="Permalink to &quot;（3）插入和取出顺序一致：LinkedHashMap&quot;">​</a></h4><h4 id="_4-配置文件操作-properties" tabindex="-1">（4）配置文件操作：Properties <a class="header-anchor" href="#_4-配置文件操作-properties" aria-label="Permalink to &quot;（4）配置文件操作：Properties&quot;">​</a></h4><h2 id="关系对比" tabindex="-1">关系对比 <a class="header-anchor" href="#关系对比" aria-label="Permalink to &quot;关系对比&quot;">​</a></h2><h3 id="arraylist-和-vector" tabindex="-1">ArrayList 和 Vector <a class="header-anchor" href="#arraylist-和-vector" aria-label="Permalink to &quot;ArrayList 和 Vector&quot;">​</a></h3><table tabindex="0"><thead><tr><th>底层结构</th><th>版本</th><th>线程安全（同步）</th><th>效率</th><th>扩容机制</th></tr></thead><tbody><tr><td>ArrayList</td><td>可变数组</td><td>jdk1.2</td><td><span style="color:red;">不安全</span>, <span style="color:red;">效率高</span></td><td>1. 如果是<span style="color:red;">无参</span>构造器, <span style="color:red;">默认为 10</span>, 满后, 就按 <span style="color:red;">1.5 倍扩容</span> <br> 2. 如果构造器<span style="color:red;">指定大小</span>, 则每次按原先的<span style="color:red;">1.5 倍扩容</span></td></tr><tr><td>Vector</td><td>可变数组 Object[]</td><td>jdk1.0</td><td><span style="color:red;">安全</span>, <span style="color:red;">效率不高</span></td><td>1. 如果是<span style="color:red;">无参</span>构造器, <span style="color:red;">默认为 10</span>, 满后, 就按 <span style="color:red;">2 倍扩容</span> <br> 2. 如果构造器<span style="color:red;">指定大小</span>, 则每次按原先的<span style="color:red;">2 倍扩容</span></td></tr></tbody></table><h3 id="arraylist-和-linkedlist" tabindex="-1">ArrayList 和 LinkedList <a class="header-anchor" href="#arraylist-和-linkedlist" aria-label="Permalink to &quot;ArrayList 和 LinkedList&quot;">​</a></h3><table tabindex="0"><thead><tr><th>底层结构</th><th>底层实现</th><th>查找的效率</th></tr></thead><tbody><tr><td>ArrayList（适用查找多）</td><td>可变数组</td><td><span style="color:red;">较低</span></td></tr><tr><td>LinkedList（适用增删多）</td><td>双向链表</td><td><span style="color:red;">较高</span>，通过链表添加</td></tr></tbody></table><h3 id="hashmap-和-hashtable" tabindex="-1">HashMap 和 Hashtable <a class="header-anchor" href="#hashmap-和-hashtable" aria-label="Permalink to &quot;HashMap 和 Hashtable&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>版本</th><th>线程安全（同步）</th><th>效率</th><th>允许 null 键 null 值</th></tr></thead><tbody><tr><td>HashMap</td><td>1.2</td><td>不安全</td><td>高</td><td>可以</td></tr><tr><td>Hashtable</td><td>1.0</td><td>安全</td><td><span style="color:red;">低</span></td><td>不可以</td></tr></tbody></table>',36)])])}const x=d(h,[["render",n]]);export{_ as __pageData,x as default};
